import {createScene} from './scene.mjs';import {measure,heightUnder,stepTip,STOPS,REACH} from './model.mjs';
/** Hover, keyboard stops and spring response retained; optional tour is explicit. */
export function mount({root,kit,config,initialState}){
 const stage=createScene({kit,config}),svg=root.querySelector('svg'),controls=root.querySelector('[data-controls]'),readout=root.querySelector('[data-live-readout]'),abort=new AbortController(),opts={signal:abort.signal},still=matchMedia('(prefers-reduced-motion: reduce)');
 let state={...initialState},target=state.carriageX,tip={at:state.tipHeight,rate:0},frame=0,last=0,clock=0,touring=false,disposed=false,visible=true;
 stage.update(state);const view=stage.mount(svg.querySelector('[data-scene]'));root.__stage=stage;
 const label=document.createElement('label'),input=document.createElement('input'),tour=document.createElement('button');label.textContent='Carriage position (drawing px)';input.type='range';input.min=REACH[0];input.max=REACH[1];input.step=.1;input.value=target;label.append(input);tour.textContent='Play block tour';controls.replaceChildren(label,tour);svg.tabIndex=0;svg.setAttribute('role','slider');svg.setAttribute('aria-label','Dial indicator carriage; arrow keys choose blocks');svg.setAttribute('aria-valuemin','0');svg.setAttribute('aria-valuemax','18');
 const draw=()=>{const m=stage.update(state);view.update();readout.textContent=m.reading;root.querySelector('[data-part="static-readout"]').textContent=m.reading;svg.setAttribute('aria-valuenow',String(m.height));svg.setAttribute('aria-valuetext',m.reading);input.value=state.carriageX;root.dispatchEvent(new CustomEvent('crafted:state',{detail:{state,readout:m.reading}}));};
 const immediate=()=>!config.motion.enabled||still.matches;
 const tick=now=>{frame=0;const dt=last?Math.min((now-last)/1000,1/30):1/60;last=now;if(touring){clock+=dt;target=STOPS[Math.floor(clock/2.2)%3];}state.carriageX+= (target-state.carriageX)*(1-Math.exp(-dt/.28));if(Math.abs(target-state.carriageX)<.01)state.carriageX=target;tip=stepTip(tip,heightUnder(state.carriageX),dt);state.tipHeight=tip.at;draw();if(visible&&!document.hidden&&(touring||state.carriageX!==target||tip.rate!==0))frame=requestAnimationFrame(tick);};
 const run=()=>{if(disposed)return;if(immediate()){touring=false;state={carriageX:target,tipHeight:heightUnder(target)};tip={at:state.tipHeight,rate:0};draw();}else if(!frame&&visible&&!document.hidden){last=0;frame=requestAnimationFrame(tick);}};
 const steer=x=>{touring=false;tour.textContent='Play block tour';target=Math.max(REACH[0],Math.min(REACH[1],x));run();};
 input.addEventListener('input',()=>steer(Number(input.value)),opts);svg.addEventListener('pointermove',e=>{const b=svg.getBoundingClientRect(),share=Math.max(0,Math.min(1,((e.clientX-b.left)/b.width-.25)/.5));steer(REACH[0]+share*(REACH[1]-REACH[0]));},opts);
 svg.addEventListener('keydown',e=>{const here=STOPS.reduce((best,x,i)=>Math.abs(x-target)<Math.abs(STOPS[best]-target)?i:best,0);let to=null;if(['ArrowRight','ArrowUp'].includes(e.key))to=Math.max(0,here-1);if(['ArrowLeft','ArrowDown'].includes(e.key))to=Math.min(2,here+1);if(e.key==='Home')to=0;if(e.key==='End')to=2;if(to!==null){e.preventDefault();steer(STOPS[to]);}},opts);
 tour.addEventListener('click',()=>{touring=!touring;clock=0;tour.textContent=touring?'Pause block tour':'Play block tour';run();},opts);
 const stop=()=>{cancelAnimationFrame(frame);frame=0;};const observer=new IntersectionObserver(entries=>{visible=entries.at(-1).isIntersecting;if(visible)run();else stop();});observer.observe(root);document.addEventListener('visibilitychange',()=>document.hidden?stop():run(),opts);still.addEventListener('change',run,opts);draw();
 return {getState:()=>({...state}),setState(next){measure(next);stop();state={...next};target=state.carriageX;tip={at:state.tipHeight,rate:0};touring=false;draw();},pause(){touring=false;stop();},resume:run,getStats:()=>({pendingFrame:!!frame}),dispose(){if(disposed)return;disposed=true;stop();observer.disconnect();abort.abort();view.dispose();stage.dispose();controls.replaceChildren();delete root.__stage;}};
}
